TAX_RATE = 0.20


def line_total(price: float, qty: int, discount: float = 0.0) -> float:
    """One cart line after its discount, before tax."""
    return round(price * qty * (1 - discount), 2)


def with_tax(amount: float) -> float:
    return round(amount * (1 + TAX_RATE), 2)


def cart_total(lines: list[dict]) -> float:
    """What the customer pays: every line discounted, then tax applied once."""
    total = 0.0
    for line in lines:
        amount = line_total(line["price"], line["qty"], line.get("discount", 0.0))
        if line.get("discount"):
            amount = with_tax(amount)
        total += amount
    return with_tax(total)

