import unittest

from cart import cart_total, line_total


class CartTest(unittest.TestCase):
    def test_line_total_applies_discount(self):
        self.assertEqual(line_total(10.0, 3, 0.5), 15.0)

    def test_cart_total_taxes_once(self):
        self.assertEqual(cart_total([{"price": 10.0, "qty": 2}]), 24.0)

    def test_empty_cart(self):
        self.assertEqual(cart_total([]), 0.0)


if __name__ == "__main__":
    unittest.main()

